    private fun g(a: App, topic: String, title: String, summary: String, steps: List<String>, alt: List<String>, kw: String, warn: String? = null): Guide =
        Guide(
            "msg-${a.id}-$topic", "${a.name}: $title", cat, summary, steps,
            alt + (if (a.known) emptyList() else listOf(GENERIC_MENU)) + NO_ACCESS,
            warn ?: a.warn, links = listOf(GuideLink("وب‌سایت رسمی ${a.name}", a.site)),
            keywords = "پیام رسان ${a.name} ${a.kw} $kw", group = a.name,
            appliesTo = "نسخهٔ فعلی برنامه روی اندروید ۸ تا ۱۵", volatile = true
        )

